import Link from "next/link";
import type { ReactNode } from "react";
import { ArrowRight, Code, InfoCircle } from "reicon-react";
import { Alert } from "../../../components/vip-ui/alert";
import { Avatar } from "../../../components/vip-ui/avatar";
import { Badge } from "../../../components/vip-ui/badge";
import { ButtonLink } from "../../../components/vip-ui/button-link";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../../components/vip-ui/card";
import {
  EmptyState,
  EmptyStateActions,
  EmptyStateDescription,
  EmptyStateIcon,
  EmptyStateTitle,
} from "../../../components/vip-ui/empty-state";
