export function formatDate(value: string | null) {
  if (!value) return "Not published";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}

export function Heading({
  title,
  description,
  action,
}: {
  title: string;
  description: string;
  action?: ReactNode;
}) {
  return (
    <header className="mb-8 flex flex-wrap items-end justify-between gap-5">
      <div className="max-w-2xl">
        <h1 className="text-[clamp(2rem,4vw,3.25rem)] font-semibold leading-[1.08] tracking-[-0.06em]">
          {title}
        </h1>
        <p className="mt-3 text-sm leading-6 text-muted-foreground sm:text-[15px]">
          {description}
        </p>
      </div>
      {action}
    </header>
  );
}

export function Source({ asOf }: { asOf: string | null }) {
  const received = asOf
    ? new Intl.DateTimeFormat("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
        hour: "numeric",
        minute: "2-digit",
        timeZone: "UTC",
        timeZoneName: "short",
      }).format(new Date(asOf))
    : null;
  return (
    <p className="mt-5 text-xs leading-5 text-muted-foreground">
      Source:{" "}
      <a
        className="underline underline-offset-4 hover:text-foreground"
        href={repository.url}
      >
        GitHub
      </a>
      {received ? ` · API response ${received}` : ""}
      {" · Updates every 5 minutes"}
    </p>
  );
}

export function Failure() {
  return (
    <Alert
      variant="warning"
      title="GitHub data is unavailable"
      className="max-w-2xl"
    >
      GitHub may be unavailable or the API rate limit may have been reached. Try
      again shortly, or{" "}
      <a className="underline underline-offset-4" href={repository.url}>
        open the repository on GitHub
      </a>
      .
    </Alert>
  );
}

export function NoResults({
